package sodresoftwares.barbearia.ports;

import sodresoftwares.barbearia.dto.billing.CheckoutResponseDTO;
import sodresoftwares.barbearia.model.billing.PaymentMethod;
import sodresoftwares.barbearia.model.business.Business;
import sodresoftwares.barbearia.model.billing.Plan;
import sodresoftwares.barbearia.dto.billing.CreditCardDTO;
import sodresoftwares.barbearia.dto.billing.CreditCardHolderDTO;

import java.time.LocalDate;

public interface PaymentGatewayPort {

    /**
     * Creates (or retrieves) the customer in the Payment Gateway.
     * Returns the customer ID generated by the external API (e.g., cus_000005030805).
     */
    String createOrUpdateCustomer(Business business);

    /**
     * Processes the subscription directly using a credit card (Transparent Checkout).
     * Returns the subscription ID generated by Asaas and the credit card tokenization data.
     */
    GatewayCreditCardResponse processCreditCardCheckout(
            Business business,
            Plan plan,
            String gatewayCustomerId,
            String creditCardToken,
            CreditCardDTO creditCard,
            CreditCardHolderDTO holderInfo
    );

    /**
     * Updates the credit card on an active subscription in the Gateway.
     */
    GatewayCreditCardResponse updateSubscriptionPaymentMethod(
            String gatewaySubscriptionId,
            PaymentMethod paymentMethod,
            String creditCardToken,
            CreditCardDTO creditCard,
            CreditCardHolderDTO holderInfo
    );

    /**
     * Creates a new subscription in the Gateway scheduled to charge on a specific future date.
     * Used for upgrades/downgrades to maintain the current billing cycle without double charging.
     */
    GatewayCreditCardResponse createScheduledSubscription(
            Business business,
            Plan plan,
            String gatewayCustomerId,
            PaymentMethod paymentMethod,
            String creditCardToken,
            CreditCardDTO creditCard,
            CreditCardHolderDTO holderInfo,
            LocalDate nextDueDate
    );

    /**
     * Tokenizes a credit card in the Gateway to obtain the official Brand and last 4 digits.
     */
    GatewayCreditCardResponse tokenizeCreditCard(
            String gatewayCustomerId,
            CreditCardDTO creditCard,
            CreditCardHolderDTO holderInfo
    );

    /**
     * Processes a PIX subscription checkout.
     * Returns the PIX QR Code payload and Base64 image for the first invoice.
     */
    CheckoutResponseDTO processPixCheckout(Business business, Plan plan, String gatewayCustomerId);

    /**
     * Retrieves the PIX QR Code for an already existing pending subscription.
     * Used to recover the payment info without generating a duplicate subscription in the gateway.
     */
    CheckoutResponseDTO getPendingPixQrCode(String gatewaySubscriptionId);

    /**
     * Retrieves the PIX QR Code directly from a specific gateway invoice ID.
     */
    CheckoutResponseDTO getPixQrCodeByInvoiceId(String gatewayInvoiceId);

    /**
     * Cancels the active subscription in the Gateway.
     */
    void cancelSubscription(String gatewaySubscriptionId);

    // The response now focuses on vital credit card data instead of a redirection URL
    record GatewayCreditCardResponse(
            String gatewaySubscriptionId,
            String creditCardToken,
            String cardBrand,
            String lastFourDigits
    ) {
    }
}